#!/usr/bin/env python3
"""AIRTAXI_NOISEWIND1 analysis (registration planned/AIRTAXI_NOISEWIND1_PREREG.md). Reads out/airtaxi_noisewind1_*.json; writes planned/airtaxi_noisewind1_results_table.md."""
import json, glob, statistics as st
rows = [r for f in sorted(glob.glob('out/airtaxi_noisewind1_[0-9]*.json')) for r in json.load(open(f))]
def get(m, li, mode, key): return [r[key] for r in rows if r['metro'] == m and r['li'] == li and r['mode'] == mode]
P = []
def chk(n, ok, t): P.append((n, ok, t)); print('PASS' if ok else 'FAIL', n, t)
cells = [(m, li) for m in ('DFW', 'HOU') for li in range(3)]
chk('P1', all(r['popDNL65'] == 0 and r['cells65'] == 0 for r in rows), f"max off-site DNL over all {len(rows)} runs {max(r['dnlOffsiteMax'] for r in rows):.1f} dB; cells >= 65: {sum(r['cells65'] for r in rows)}")
dd = [st.median(get(m, li, 'wind', 'dnlOffsiteMax')) - st.median(get(m, li, 'line', 'dnlOffsiteMax')) for m, li in cells]
chk('P2', all(abs(x) < 1.5 for x in dd), 'peak off-site DNL, wind - line: ' + ', '.join(f'{x:+.2f}' for x in dd))
ch = []
for m, li in cells:
    a, b = st.median(get(m, li, 'line', 'popN55_10')), st.median(get(m, li, 'wind', 'popN55_10')); ch.append((a, b, (abs(b - a) / a if a else (float('inf') if b else 0))))
chk('P3', sum(1 for _, _, c in ch if c > 0.2) >= 3, 'people with >= 10 loud flights, line -> wind: ' + '; '.join(f'{a:,.0f} -> {b:,.0f}' for a, b, _ in ch))
chk('P4', all(st.median(get(m, li, 'wind', 'popDNL55')) == 0 for m, li in cells), 'median people at DNL >= 55, wind: ' + ', '.join(f"{st.median(get(m, li, 'wind', 'popDNL55')):,.0f}" for m, li in cells))
cc = [(st.median(get(m, li, 'line', 'cellsN55_1')), st.median(get(m, li, 'wind', 'cellsN55_1'))) for m, li in cells]
chk('P5', sum(1 for a, b in cc if b > a) >= 5, 'off-site cells with >= 1 loud flight, line -> wind: ' + '; '.join(f'{a:g} -> {b:g}' for a, b in cc))
npass = sum(1 for _, ok, _ in P if ok); print(f'{npass} of {len(P)} passed')
L = ['# AIRTAXI_NOISEWIND1 results table (generated by planned/airtaxi_noisewind1_analyze.py)', '', f'{npass} of {len(P)} predictions passed. Runs: {len(rows)}.', ''] + [f'- {"PASS" if ok else "FAIL"} {n}: {t}' for n, ok, t in P]
L += ['', '## Medians over 5 seeds, window 06:00-18:00', '', '| Metro | Trips/h | Mode | Peak off-site DNL (dB) | People >= 10 loud flights | >= 50 loud flights | People at DNL >= 55 | Off-site cells with >= 1 loud flight |', '|---|---|---|---|---|---|---|---|']
for m, li in cells:
    T = [r['T'] for r in rows if r['metro'] == m and r['li'] == li][0]
    for md in ('line', 'wind'):
        L.append(f"| {m} | {T:g} | {md} | {st.median(get(m, li, md, 'dnlOffsiteMax')):.1f} | {st.median(get(m, li, md, 'popN55_10')):,.0f} | {st.median(get(m, li, md, 'popN55_50')):,.0f} | {st.median(get(m, li, md, 'popDNL55')):,.0f} | {st.median(get(m, li, md, 'cellsN55_1')):g} |")
L += ['', 'Wind days drawn (seed 1-5): ' + '; '.join(f"{m}: " + ', '.join(sorted({r['windDay'] for r in rows if r['metro'] == m and r['mode'] == 'wind'})) for m in ('DFW', 'HOU'))]
open('planned/airtaxi_noisewind1_results_table.md', 'w').write('\n'.join(L) + '\n'); print('wrote planned/airtaxi_noisewind1_results_table.md')
